import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.DA0HUBZR.js";const b=JSON.parse('{"title":"接口自动化高频面试题（带答案）","description":"","frontmatter":{},"headers":[],"relativePath":"kb/interview-api.md","filePath":"kb/interview-api.md","lastUpdated":1794882424000}'),o={name:"kb/interview-api.md"};function h(l,a,n,d,c,u){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="接口自动化高频面试题-带答案" tabindex="-1">接口自动化高频面试题（带答案） <a class="header-anchor" href="#接口自动化高频面试题-带答案" aria-label="Permalink to &quot;接口自动化高频面试题（带答案）&quot;">​</a></h1><p>这页收的是面试里反复出现的题，答案按「能直接说出口」的长度写。每题都给了追问方向，面试官往下问时不至于卡住。</p><h2 id="一、基础与协议" tabindex="-1">一、基础与协议 <a class="header-anchor" href="#一、基础与协议" aria-label="Permalink to &quot;一、基础与协议&quot;">​</a></h2><h3 id="_1-接口测试到底在测什么" tabindex="-1">1. 接口测试到底在测什么？ <a class="header-anchor" href="#_1-接口测试到底在测什么" aria-label="Permalink to &quot;1. 接口测试到底在测什么？&quot;">​</a></h3><p>测「契约」：请求该怎么发、响应该长什么样、边界和异常怎么处理。具体拆成七块——方法、路径、参数位置、请求头、状态码、响应体结构、错误码。断言落在这七块上，才算测了接口，而不只是「调通了」。</p><blockquote><p>追问：那接口测试和集成测试的区别？——接口测试聚焦单个契约，集成测试关注多个服务串起来后的行为和数据一致性。</p></blockquote><h3 id="_2-401-和-403-怎么区分" tabindex="-1">2. 401 和 403 怎么区分？ <a class="header-anchor" href="#_2-401-和-403-怎么区分" aria-label="Permalink to &quot;2. 401 和 403 怎么区分？&quot;">​</a></h3><p>401 是「没认证」：没带 token、token 过期、签名不对，客户端应该去登录。403 是「认证过了但没权限」：普通用户访问管理接口。测试时 401 用「不带 token / 过期 token」，403 用「低权限账号访问高权限接口」。</p><h3 id="_3-put-和-patch-的区别-测试要注意什么" tabindex="-1">3. PUT 和 PATCH 的区别，测试要注意什么？ <a class="header-anchor" href="#_3-put-和-patch-的区别-测试要注意什么" aria-label="Permalink to &quot;3. PUT 和 PATCH 的区别，测试要注意什么？&quot;">​</a></h3><p>PUT 是整体替换：没传的字段会被置空或删掉，所以测试要验「只传部分字段后，其余字段是否被清空」。PATCH 是局部更新，只改传入的字段。两个都要测非法字段、类型错误、不存在资源（404）。</p><h3 id="_4-幂等怎么测" tabindex="-1">4. 幂等怎么测？ <a class="header-anchor" href="#_4-幂等怎么测" aria-label="Permalink to &quot;4. 幂等怎么测？&quot;">​</a></h3><p>看有没有幂等键。有键：同一个键连发两次，断言第二次返回 200（不是 201）、body 里的 id 与第一次相同、库里只有一条。没键：重复提交按业务规则处理，通常第二次返回 409 或返回同一结果，要按文档断言。</p><h3 id="_5-一个创建接口返回-200-而不是-201-算-bug-吗" tabindex="-1">5. 一个创建接口返回 200 而不是 201，算 bug 吗？ <a class="header-anchor" href="#_5-一个创建接口返回-200-而不是-201-算-bug-吗" aria-label="Permalink to &quot;5. 一个创建接口返回 200 而不是 201，算 bug 吗？&quot;">​</a></h3><p>先看契约。REST 惯例是 201 + <code>Location</code>，但如果接口文档明确写 200，就按 200 断言——同时把「与惯例不一致」提出来，因为它影响客户端缓存和幂等设计。判断标准永远是文档，不是个人习惯。</p><h2 id="二、用例设计" tabindex="-1">二、用例设计 <a class="header-anchor" href="#二、用例设计" aria-label="Permalink to &quot;二、用例设计&quot;">​</a></h2><h3 id="_6-给你一个接口-你怎么设计用例" tabindex="-1">6. 给你一个接口，你怎么设计用例？ <a class="header-anchor" href="#_6-给你一个接口-你怎么设计用例" aria-label="Permalink to &quot;6. 给你一个接口，你怎么设计用例？&quot;">​</a></h3><p>按维度铺：参数（必填、类型、长度、枚举、位置）、鉴权（无 token、过期、越权）、状态（重复提交、并发、非法状态流转）、数据（分页边界、空集合、超长、特殊字符）、协议（方法、Content-Type、状态码、响应头）。铺完画成「接口 × 维度」矩阵，空格就是缺口。</p><h3 id="_7-边界值为什么比中间值更重要" tabindex="-1">7. 边界值为什么比中间值更重要？ <a class="header-anchor" href="#_7-边界值为什么比中间值更重要" aria-label="Permalink to &quot;7. 边界值为什么比中间值更重要？&quot;">​</a></h3><p>bug 集中在边界：0、1、最大值、超一位、空串、null。中间值大多走同一条代码路径，测十个和测一个没区别。分页就测第 1 页、最后一页、越界页；金额就测 0、0.01、上限、上限 + 0.01。</p><h3 id="_8-用例之间能依赖顺序吗" tabindex="-1">8. 用例之间能依赖顺序吗？ <a class="header-anchor" href="#_8-用例之间能依赖顺序吗" aria-label="Permalink to &quot;8. 用例之间能依赖顺序吗？&quot;">​</a></h3><p>不能。依赖顺序意味着单独跑必挂、并行跑必挂、失败后无法重跑。需要的共享数据用夹具或工厂现造，用完清理；确实有先后关系的（向导式流程）就合并成一条链路用例。</p><h2 id="三、框架与封装" tabindex="-1">三、框架与封装 <a class="header-anchor" href="#三、框架与封装" aria-label="Permalink to &quot;三、框架与封装&quot;">​</a></h2><h3 id="_9-你的框架分几层" tabindex="-1">9. 你的框架分几层？ <a class="header-anchor" href="#_9-你的框架分几层" aria-label="Permalink to &quot;9. 你的框架分几层？&quot;">​</a></h3><p>四层：配置（环境、域名、超时、账号）、客户端（发请求、重试、日志、异常）、接口（按业务域封装具体接口，如 <code>UserApi.login</code>）、用例（组织场景与断言）。分层的目的是一处改动只影响一层。</p><h3 id="_10-为什么重试只对幂等方法开放" tabindex="-1">10. 为什么重试只对幂等方法开放？ <a class="header-anchor" href="#_10-为什么重试只对幂等方法开放" aria-label="Permalink to &quot;10. 为什么重试只对幂等方法开放？&quot;">​</a></h3><p>非幂等重试会产生重复副作用：重复下单、重复扣款。POST 要重试必须带幂等键且服务端去重。另外只对 5xx 和连接错误重试——4xx 是请求本身有问题，重试一百次结果一样。</p><h3 id="_11-怎么让封装本身可测" tabindex="-1">11. 怎么让封装本身可测？ <a class="header-anchor" href="#_11-怎么让封装本身可测" aria-label="Permalink to &quot;11. 怎么让封装本身可测？&quot;">​</a></h3><p>依赖注入。把「真正发请求的函数」作为参数传进客户端，测试时传假实现，就能断言重试次数、异常类型、URL 拼接、头合并，不用起服务。这一层不测，「框架有 bug」和「接口有 bug」就永远分不清。</p><h3 id="_12-日志该记什么、不该记什么" tabindex="-1">12. 日志该记什么、不该记什么？ <a class="header-anchor" href="#_12-日志该记什么、不该记什么" aria-label="Permalink to &quot;12. 日志该记什么、不该记什么？&quot;">​</a></h3><p>记方法、路径、状态码、耗时、重试次数、请求 id；不记 Authorization、Cookie、密码、完整手机号和身份证。响应体只在失败时记，并截断长度（比如 500 字符）。</p><h2 id="四、数据与执行" tabindex="-1">四、数据与执行 <a class="header-anchor" href="#四、数据与执行" aria-label="Permalink to &quot;四、数据与执行&quot;">​</a></h2><h3 id="_13-测试数据从哪来" tabindex="-1">13. 测试数据从哪来？ <a class="header-anchor" href="#_13-测试数据从哪来" aria-label="Permalink to &quot;13. 测试数据从哪来？&quot;">​</a></h3><p>三种来源，优先级从高到低：调接口造（最真实，但造数接口本身可能有 bug）、直接写库（快，但绕过业务校验）、固定数据（只适合只读查询）。造数要保证唯一性，否则第二轮就撞 409。</p><h3 id="_14-数据清理失败怎么办" tabindex="-1">14. 数据清理失败怎么办？ <a class="header-anchor" href="#_14-数据清理失败怎么办" aria-label="Permalink to &quot;14. 数据清理失败怎么办？&quot;">​</a></h3><p>清理写在夹具 <code>yield</code> 之后并 <code>try/except</code> 包住：失败只记警告，不把用例判红——否则清理问题会掩盖业务问题。同时给数据加唯一前缀，方便定期批量清理。</p><h3 id="_15-并发用例怎么断言" tabindex="-1">15. 并发用例怎么断言？ <a class="header-anchor" href="#_15-并发用例怎么断言" aria-label="Permalink to &quot;15. 并发用例怎么断言？&quot;">​</a></h3><p>断言「状态组合」，不断言「谁赢」。比如两个线程同时支付同一订单，结果应该是 <code>{200, 409}</code> 这样的集合；断言「第一个一定成功」会因线程调度随机变红。</p><h2 id="五、报告与-ci" tabindex="-1">五、报告与 CI <a class="header-anchor" href="#五、报告与-ci" aria-label="Permalink to &quot;五、报告与 CI&quot;">​</a></h2><h3 id="_16-报告里最该看什么" tabindex="-1">16. 报告里最该看什么？ <a class="header-anchor" href="#_16-报告里最该看什么" aria-label="Permalink to &quot;16. 报告里最该看什么？&quot;">​</a></h3><p>先看失败的用例名和断言消息（是否可判定），再看失败是否集中在某个接口或某个维度，最后看耗时趋势。通过率是结论，不是线索。</p><h3 id="_17-ci-上的偶发失败怎么治理" tabindex="-1">17. CI 上的偶发失败怎么治理？ <a class="header-anchor" href="#_17-ci-上的偶发失败怎么治理" aria-label="Permalink to &quot;17. CI 上的偶发失败怎么治理？&quot;">​</a></h3><p>先分类：环境（端口未就绪、连接超时）、数据（唯一性冲突、清理失败）、时序（异步未完成）、真 bug。分别用等待策略、数据隔离、重试解决；给不稳定的用例打 <code>flaky</code> 标记并限期修，不要长期靠重试掩盖。</p><h3 id="_18-为什么-ci-不该跑依赖外网的用例" tabindex="-1">18. 为什么 CI 不该跑依赖外网的用例？ <a class="header-anchor" href="#_18-为什么-ci-不该跑依赖外网的用例" aria-label="Permalink to &quot;18. 为什么 CI 不该跑依赖外网的用例？&quot;">​</a></h3><p>外网不稳定会导致随机失败，外部服务会变更、会限流，还可能涉及密钥。CI 必须可重复、可离线、可并行。要测外部依赖，用 mock 或专门的联调环境，单独一条流水线。</p><h2 id="六、ai-与接口测试" tabindex="-1">六、AI 与接口测试 <a class="header-anchor" href="#六、ai-与接口测试" aria-label="Permalink to &quot;六、AI 与接口测试&quot;">​</a></h2><h3 id="_19-ai-生成用例-你怎么保证质量" tabindex="-1">19. AI 生成用例，你怎么保证质量？ <a class="header-anchor" href="#_19-ai-生成用例-你怎么保证质量" aria-label="Permalink to &quot;19. AI 生成用例，你怎么保证质量？&quot;">​</a></h3><p>三步：先给覆盖矩阵（接口 × 维度），让 AI 按格子填；提示词里写死输出 schema 和硬约束（期望结果必须可判定）；生成后过五道审——可执行、可判定、不重复、前置清楚、数据可造。审完通常删三分之一、改三分之一。</p><h3 id="_20-ai-在接口测试里真正擅长什么" tabindex="-1">20. AI 在接口测试里真正擅长什么？ <a class="header-anchor" href="#_20-ai-在接口测试里真正擅长什么" aria-label="Permalink to &quot;20. AI 在接口测试里真正擅长什么？&quot;">​</a></h3><p>擅长：从接口文档提取字段和约束、把需求拆成测试点、生成边界组合、把失败日志翻译成人话。不擅长：判断业务规则对不对、决定哪些该自动化、替代人工做最终归因。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>每章末尾的「面试题」小节是按章节主题写的，配着笔记看更顺。</li><li>更新规则见 <a href="/shenle-ai-qa/kb/rules">内容更新规则</a>。</li></ul>',51)])])}const p=e(o,[["render",h]]);export{b as __pageData,p as default};
